import{_ as a,c as o,o as d,ae as l}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"使用命令","description":"MinecraftSounds 如何使用命令播放音频","frontmatter":{"title":"使用命令","description":"MinecraftSounds 如何使用命令播放音频"},"headers":[],"relativePath":"tutorials/command.md","filePath":"tutorials/command.md"}'),i={name:"tutorials/command.md"};function c(r,e,t,n,s,u){return d(),o("div",null,e[0]||(e[0]=[l('<h1 id="使用命令播放音频" tabindex="-1">使用命令播放音频 <a class="header-anchor" href="#使用命令播放音频" aria-label="Permalink to &quot;使用命令播放音频&quot;">​</a></h1><p>1.7.10及以下版本：<br><code>/playsound {soundkey} {玩家名/目标选择器} {x} {y} {z} {播放范围/半径}</code><br> 1.8及以上版本：<br><code>/playsound {soundkey} {播放源} {玩家名/目标选择器} {x} {y} {z} {播放范围/半径}</code></p><h2 id="soundkey" tabindex="-1">soundkey <a class="header-anchor" href="#soundkey" aria-label="Permalink to &quot;soundkey&quot;">​</a></h2><p>具体可到<a href="/soundkey.html">认识soundkey</a>页面了解soundkey。</p><h2 id="播放源" tabindex="-1">播放源 <a class="header-anchor" href="#播放源" aria-label="Permalink to &quot;播放源&quot;">​</a></h2><ul><li><code>master</code>：主音量</li><li><code>music</code>：音乐音量</li><li><code>record</code>：唱片机 [默认选择]</li><li><code>weather</code>：天气</li><li><code>block</code>：方块</li><li><code>neutral</code>：中立实体</li><li><code>player</code>：玩家</li><li><code>ambient</code>：环境</li><li><code>voice</code>：玩家语音 [高版本才有]</li><li><code>ui</code>：用户界面 [高版本才有]</li></ul><h2 id="目标选择器" tabindex="-1">目标选择器 <a class="header-anchor" href="#目标选择器" aria-label="Permalink to &quot;目标选择器&quot;">​</a></h2><ul><li><code>@a</code>：所有玩家</li><li><code>@p</code>：最近玩家</li><li><code>@r</code>：随机玩家</li><li><code>@s</code>：命令执行者</li></ul><h2 id="坐标" tabindex="-1">坐标 <a class="header-anchor" href="#坐标" aria-label="Permalink to &quot;坐标&quot;">​</a></h2><ul><li><code>x</code>：音频播放的X坐标</li><li><code>y</code>：音频播放的Y坐标</li><li><code>z</code>：音频播放的Z坐标</li></ul><h2 id="播放范围-半径" tabindex="-1">播放范围/半径 <a class="header-anchor" href="#播放范围-半径" aria-label="Permalink to &quot;播放范围/半径&quot;">​</a></h2><ul><li>播放范围：音频播放的范围，单位为块。</li><li>半径：音频播放的半径，单位为块。</li></ul><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><ul><li>1.7.10及以下版本：<br><code>/playsound mcsd.my_sound @a ~ ~ ~ 10000</code></li><li>1.8及以上版本：<br><code>/playsound mcsd.my_sound record @a ~ ~ ~ 10000</code></li></ul><hr><h1 id="使用命令停止音频" tabindex="-1">使用命令停止音频 <a class="header-anchor" href="#使用命令停止音频" aria-label="Permalink to &quot;使用命令停止音频&quot;">​</a></h1><p>1.8及以上高版本：<br><code>/stopsound @a</code></p>',17)]))}const p=a(i,[["render",c]]);export{m as __pageData,p as default};
